import { spawnSync } from 'node:child_process';

import { OPTION_NAMES, REFERENCE_EXECUTABLE } from '../shared/options.mjs';

export function runReferenceExecutable(values) {
  const args = [];

  for (const name of OPTION_NAMES) {
    args.push(`--${name}`, String(values[name]));
  }

  const result = spawnSync(REFERENCE_EXECUTABLE, args, {
    stdio: 'pipe',
  });

  return {
    code: typeof result.status === 'number' ? result.status : 1,
    error: result.error ?? null,
    stderr: result.stderr ?? Buffer.alloc(0),
    stdout: result.stdout ?? Buffer.alloc(0),
  };
}

