import {
  HELP_FLAGS,
  OPTION_ARGUMENT_LABELS,
  OPTION_FLAGS,
  OPTION_NAMES,
} from '../shared/options.mjs';

const MAX_USAGE_WIDTH = 78;

function buildUsageSegments() {
  return ['[-h]', ...OPTION_NAMES.map((name) => `--${name} ${OPTION_ARGUMENT_LABELS[name]}`)];
}

function isNegativeNumberLike(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function isOptionLikeValue(token) {
  return token !== '-' && token.startsWith('-') && !isNegativeNumberLike(token);
}

function buildUsage(programName) {
  const prefix = `usage: ${programName} `;
  const continuationPrefix = ' '.repeat(prefix.length);
  const lines = [];
  let currentLine = prefix;
  let hasSegmentOnLine = false;

  for (const segment of buildUsageSegments()) {
    const candidate = hasSegmentOnLine ? `${currentLine} ${segment}` : `${currentLine}${segment}`;
    if (hasSegmentOnLine && candidate.length > MAX_USAGE_WIDTH - 1) {
      lines.push(currentLine);
      currentLine = `${continuationPrefix}${segment}`;
      hasSegmentOnLine = true;
      continue;
    }

    currentLine = candidate;
    hasSegmentOnLine = true;
  }

  lines.push(currentLine);
  return `${lines.join('\n')}\n`;
}

function buildOptionsSection() {
  const lines = ['options:', '  -h, --help  show this help message and exit'];
  for (const name of OPTION_NAMES) {
    lines.push(`  --${name} ${OPTION_ARGUMENT_LABELS[name]}`);
  }
  return `${lines.join('\n')}\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

