    code: 2,
    status: 'error',
    text: buildError(programName, message),
  };
}

function createHelp(programName) {
  return {
    code: 0,
    status: 'help',
    text: `${buildUsage(programName)}\n${buildOptionsSection()}`,
  };
}

function createSuccess(values) {
  return {
    code: 0,
    status: 'ok',
    values,
  };
}

export function formatHelp(programName = 'test18.mjs') {
  return createHelp(programName).text;
}

export function parseTest18Args(argv, programName = 'test18.mjs') {
  const values = {};
  const extras = [];
  const optionFlagSet = new Set(OPTION_FLAGS);

  for (let index = 0; index < argv.length; index += 1) {
    const token = String(argv[index]);

    if (token === '-h' || token === '--help' || (token.startsWith('-h') && !token.startsWith('--') && token !== '-h=')) {
      return createHelp(programName);
    }

    if (token.startsWith('-h=')) {
      return createError(programName, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
    }

    if (token.startsWith('--help=')) {
      return createError(programName, `argument -h/--help: ignored explicit argument '${token.slice(7)}'`);
    }

    if (token === '--') {
      extras.push(...argv.slice(index).map(String));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

      if (optionFlagSet.has(flag)) {
        const name = flag.slice(2);
        if (equalsIndex !== -1) {
