    if (isOptionLikeValue(token)) {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_NAMES.filter((name) => !(name in values)).map((name) => `--${name}`);
  if (missing.length > 0) {
    return createError(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    return createError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return createSuccess(values);
